export const getRemoteParty = (serviceData) => {
    if (!serviceData) {
        return undefined;
    }
    const { personality, callingParty, calledParty } = serviceData;
    switch (personality) {
        case 'originator':
            return calledParty;
        case 'terminator':
            return callingParty;
        default:
            return undefined;
    }
};
